-- Local development seed: 200 fictional stories across the globe and the last
-- 24 hours, with 539 articles.
--
-- GENERATED by scripts/seed/generate.ts (npm run db:seed:generate). Do not edit by hand;
-- tests/seed.test.ts fails if this file and the generator disagree.
--
-- Cities are real; events and outlets are invented. Every outlet uses the reserved
-- .example domain, so no link leads anywhere. Times are relative to now(), so
-- `npm run db:reset` always yields a fresh window. `supabase db push` does not send
-- this file to a hosted project unless --include-seed is passed.

on conflict (id) do update set
  title = excluded.title,
  summary = excluded.summary,
  category = excluded.category,
  lat = excluded.lat,
  lon = excluded.lon,
  place_name = excluded.place_name,
  place_source = excluded.place_source,
  place_conf = excluded.place_conf,
  country_code = excluded.country_code,
  heat = excluded.heat,
  sentiment = excluded.sentiment,
  source_count = excluded.source_count,
  published_at = excluded.published_at,
  first_seen_at = excluded.first_seen_at,
  discussion_state = excluded.discussion_state;

on conflict (url) do update set
  story_id = excluded.story_id,
  outlet = excluded.outlet,
  outlet_country = excluded.outlet_country,
  headline = excluded.headline,
  snippet = excluded.snippet,
  published_at = excluded.published_at,
  lang = excluded.lang;
